import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './Home.css';

const HeartIcon = ({ filled }) => (
  <svg width="16" height="16" viewBox="0 0 24 24" fill={filled ? 'currentColor' : 'none'} stroke="currentColor" strokeWidth="2">
    <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/>
  </svg>
);
const BookmarkIcon = () => (
  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
    <path d="M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z"/>
  </svg>
);

const BANNERS = [
  { id: 1, emoji: '📚', title: '이번 주 추천 도서', sub: '함께 읽어볼 책을 골라봤어요' },
  { id: 2, emoji: '✍️', title: 'AI와 함께 글쓰기', sub: '나만의 독서 에세이를 써보세요' },
  { id: 3, emoji: '👥', title: '독서모임 참여하기', sub: '마음 맞는 독자들을 만나보세요' },
];

const CLUBS = [
  {
    id: 1,
    name: '<프로젝트 헤일메리>',
    time: '12:00 - 01:00',
    date: '2026.05.13',
    place: '온라인',
    current: 5,
    max: 10,
    status: '모집중',
    liked: false,
  },
  {
    id: 2,
    name: '<노르웨이의 숲> 함께 읽어요!',
    time: '19:00 - 20:30',
    date: '2026.05.14',
    place: '서울 마포구',
    current: 3,
    max: 8,
    status: '모집중',
    liked: true,
  },
];

export default function Home() {
  const navigate = useNavigate();
  const [bannerIdx, setBannerIdx] = useState(0);
  const [clubs, setClubs] = useState(CLUBS);

  const toggleLike = (id) => {
    setClubs(prev => prev.map(c => c.id === id ? { ...c, liked: !c.liked } : c));
  };

  return (
    <div className="home-page">
      {/* Banner Carousel */}
      <div className="banner-carousel">
        <div className="banner-card">
          <div className="banner-emoji">{BANNERS[bannerIdx].emoji}</div>
          <div>
            <div className="banner-title">{BANNERS[bannerIdx].title}</div>
            <div className="banner-sub">{BANNERS[bannerIdx].sub}</div>
          </div>
        </div>
        <div className="banner-dots">
          {BANNERS.map((_, i) => (
            <button
              key={i}
              className={`dot${i === bannerIdx ? ' active' : ''}`}
              onClick={() => setBannerIdx(i)}
              aria-label={`배너 ${i + 1}`}
            />
          ))}
        </div>
      </div>

      {/* Section: 독서모임 */}
      <section className="section">
        <div className="section-header">
          <h2 className="section-title">모집 중인 독서모임</h2>
          <button className="section-more" onClick={() => navigate('/community')}>전체보기</button>
        </div>

        <div className="club-list">
          {clubs.map(club => (
            <div
              key={club.id}
              className="club-card"
              onClick={() => navigate(`/community/${club.id}`)}
            >
              <div className="club-card-top">
                <div className="club-avatar">
                  <span>📖</span>
                </div>
                <div className="club-info">
                  <div className="club-name">{club.name}</div>
                  <div className="club-time">{club.time}</div>
                </div>
                <span className={`club-tag${club.status === '모집중' ? ' recruiting' : ' full'}`}>
                  {club.status}
                </span>
              </div>
              <div className="club-card-bottom">
                <span className="club-meta">{club.date} · {club.place}</span>
                <div className="club-actions">
                  <button
                    className={`action-btn${club.liked ? ' liked' : ''}`}
                    onClick={e => { e.stopPropagation(); toggleLike(club.id); }}
                    aria-label="좋아요"
                  >
                    <HeartIcon filled={club.liked} />
                  </button>
                  <button className="action-btn" onClick={e => e.stopPropagation()} aria-label="북마크">
                    <BookmarkIcon />
                  </button>
                  <span className="member-count">{club.current}/{club.max}</span>
                </div>
              </div>
            </div>
          ))}
        </div>
      </section>
    </div>
  );
}
